/**
 * Keyboard input handler for CLI
 *
 * Provides cross-runtime keyboard input handling for interactive CLI features.
 * Uses platform abstractions for Deno, Node.js, and Bun runtimes.
 */
import { isStdoutTTY } from "../../src/platform/index.js";
import { getStdinReader, setRawMode } from "../../src/platform/index.js";
export function dispatchKeyPress(key, options) {
    if (key >= "1" && key <= "9") {
        options.onNumber?.(Number.parseInt(key, 10));
        return;
    }
    switch (key.toLowerCase()) {
        case "?":
            options.onHelp?.();
            return;
        case "o":
            options.onOpen?.();
            return;
        case "c":
            options.onClear?.();
            return;
        case "q":
            options.onQuit?.();
            return;
        case "a":
            options.onAuth?.();
            return;
        case "s":
            options.onSync?.();
            return;
        case "l":
            options.onLogs?.();
            return;
        case "p":
            options.onPull?.();
            return;
        case "u":
            options.onPush?.();
            return;
    }
}
function createNoopHandler() {
    return { start() { }, stop() { } };
}
function createPlatformHandler(options) {
    let running = false;
    let reader = null;
    async function readLoop() {
        while (running) {
            try {
                if (!reader)
                    return;
                const { value, done } = await reader.read();
                if (done || !value)
                    return;
                const byte = value[0];
                if (byte === undefined)
                    continue;
                if (byte === 0x03) {
                    options.onQuit?.();
                    return;
                }
                dispatchKeyPress(String.fromCharCode(byte), options);
            }
            catch {
                return;
            }
        }
    }
    function start() {
        if (!isStdoutTTY())
            return;
        try {
            setRawMode(true);
            reader = getStdinReader();
            running = true;
            void readLoop();
        }
        catch {
            // Failed to set raw mode, keyboard shortcuts won't work
        }
    }
    function stop() {
        running = false;
        try {
            reader?.releaseLock();
            reader = null;
            setRawMode(false);
        }
        catch {
            // Ignore errors restoring terminal
        }
    }
    return { start, stop };
}
/**
 * Create a keyboard handler for the current runtime
 * Uses platform abstractions that work across Deno, Node.js, and Bun
 */
export function createKeyboardHandler(options) {
    if (!isStdoutTTY())
        return createNoopHandler();
    return createPlatformHandler(options);
}
